    }
EOF
    snippet NEW <<'EOF'
    private static func emitCoarsePassDiagnostic(_ diagnostic: CoarsePassWindowDiagnostic) {
        Task.detached { Self.coarsePassDiagnosticObserver?(diagnostic) }
    }
EOF
    patch "$file" "$OLD" "$NEW" ;;

